import unittest
import json
import os
from mcc_full_mot import run_mot

class TestMCCMOT(unittest.TestCase):
    """Integration test for the MCC MOT suite."""

    @classmethod
    def setUpClass(cls):
        """Load a minimal configuration used by the MOT runner."""
        cls.config_path = os.path.abspath(
            os.path.join(os.path.dirname(__file__), "..", "mcc_config.json")
        )
        # Ensure the config exists – create a default if missing.
        if not os.path.exists(cls.config_path):
            default_cfg = {
                "log_level": "INFO",
                "output_dir": "mcc_logs",
                "tests": ["108-check MOT test suite"]
            }
            with open(cls.config_path, "w") as f:
                json.dump(default_cfg, f, indent=2)

    def test_mot_all_pass(self):
        """Run the full MOT suite and assert that all 108 checks pass."""
        result = run_mot(self.config_path)
        self.assertEqual(
            result,
            {"total": 108, "passed": 108, "failed": 0},
            msg="MOT suite did not report all‑clear."
        )

    def test_output_directory_created(self):
        """Verify that the MOT runner creates the expected output directory."""
        output_dir = os.path.join(os.path.dirname(self.config_path), "mcc_logs")
        # Clean up any previous run
        if os.path.isdir(output_dir):
            import shutil
            shutil.rmtree(output_dir)

        run_mot(self.config_path)  # Trigger creation
        self.assertTrue(
            os.path.isdir(output_dir),
            msg="MOT output directory was not created."
        )

if __name__ == "__main__":
    unittest.main()
